import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment, balanceDue, totalPaid } from '../src/payments.js';

test('balanceDue returns invoice total when no payments exist', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;
  const balance = balanceDue(issued);
  assert.equal(balance, 102850);
});

test('balanceDue decreases after recording a payment', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;
  const beforePayment = balanceDue(issued);

  const paymentResult = recordPayment(issued, { amount: 10000, date: '2026-10-08' });
  const afterPayment = balanceDue(paymentResult.value);

  assert.equal(beforePayment - afterPayment, 10000);
});

test('totalPaid returns 0 when no payments exist', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  assert.equal(totalPaid(invoice), 0);
});

test('totalPaid sums all payments', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  let current = issued;
  current = recordPayment(current, { amount: 10000, date: '2026-10-08' }).value;
  current = recordPayment(current, { amount: 20000, date: '2026-10-09' }).value;

  assert.equal(totalPaid(current), 30000);
});

test('recordPayment adds payment to an issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const result = recordPayment(issued, { amount: 10000, date: '2026-10-08' });
  assert.equal(result.ok, true);
  assert.equal(result.value.payments.length, 1);
  assert.equal(result.value.payments[0].amount, 10000);
  assert.equal(result.value.payments[0].date, '2026-10-08');
});

test('recordPayment sets status to partially_paid when balance remains', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const result = recordPayment(issued, { amount: 10000, date: '2026-10-08' });
  assert.equal(result.value.status, 'partially_paid');
});

test('recordPayment sets status to paid when balance is fully covered', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const total = balanceDue(issued);
  const result = recordPayment(issued, { amount: total, date: '2026-10-08' });
  assert.equal(result.value.status, 'paid');
});

test('recordPayment allows payment on partially_paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const partial = recordPayment(issued, { amount: 50000, date: '2026-10-08' }).value;
  assert.equal(partial.status, 'partially_paid');

  const remaining = balanceDue(partial);
  const result = recordPayment(partial, { amount: remaining, date: '2026-10-09' });
  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment reports NOT_ISSUED for draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;

  const result = recordPayment(invoice, { amount: 10000, date: '2026-10-08' });
  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports NOT_ISSUED for paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const total = balanceDue(issued);
  const paid = recordPayment(issued, { amount: total, date: '2026-10-08' }).value;

  const result = recordPayment(paid, { amount: 1000, date: '2026-10-09' });
  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports AMOUNT_INVALID for non-positive amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const result1 = recordPayment(issued, { amount: 0, date: '2026-10-08' });
  assert.deepEqual(result1, { ok: false, error: 'AMOUNT_INVALID' });

  const result2 = recordPayment(issued, { amount: -1000, date: '2026-10-08' });
  assert.deepEqual(result2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports AMOUNT_INVALID for non-integer amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const result = recordPayment(issued, { amount: 1000.50, date: '2026-10-08' });
  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports OVERPAYMENT if payment exceeds balance due', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const total = balanceDue(issued);
  const result = recordPayment(issued, { amount: total + 1, date: '2026-10-08' });
  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment reports OVERPAYMENT even when overpaying multiple times', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const first = recordPayment(issued, { amount: 50000, date: '2026-10-08' }).value;
  const remaining = balanceDue(first);

  const result = recordPayment(first, { amount: remaining + 1, date: '2026-10-09' });
  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment reports DATE_INVALID for invalid date', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const result = recordPayment(issued, { amount: 10000, date: '2026-13-01' });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('recordPayment does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  const before = JSON.stringify(issued);
  recordPayment(issued, { amount: 10000, date: '2026-10-08' });
  const after = JSON.stringify(issued);

  assert.equal(before, after);
});

test('recordPayment correctly transitions from issued to partially_paid to paid', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  assert.equal(issued.status, 'issued');

  let current = issued;
  current = recordPayment(current, { amount: 30000, date: '2026-10-08' }).value;
  assert.equal(current.status, 'partially_paid');

  current = recordPayment(current, { amount: 30000, date: '2026-10-09' }).value;
  assert.equal(current.status, 'partially_paid');

  const remaining = balanceDue(current);
  current = recordPayment(current, { amount: remaining, date: '2026-10-10' }).value;
  assert.equal(current.status, 'paid');
});

test('recordPayment accumulates payments in the array', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const invoice = invoiceResult.value;
  const issued = issueInvoice(invoice, []).value;

  let current = issued;
  current = recordPayment(current, { amount: 10000, date: '2026-10-08' }).value;
  assert.equal(current.payments.length, 1);

  current = recordPayment(current, { amount: 20000, date: '2026-10-09' }).value;
  assert.equal(current.payments.length, 2);

  current = recordPayment(current, { amount: 15000, date: '2026-10-10' }).value;
  assert.equal(current.payments.length, 3);

  assert.equal(current.payments[0].date, '2026-10-08');
  assert.equal(current.payments[1].date, '2026-10-09');
  assert.equal(current.payments[2].date, '2026-10-10');
});

